# Big Calls questions. S = single best answer, M = select all (never all correct).
# (type, level, domain, call, scale or None, question, answer or options, wrongs, explanation)
def S(lv, cat, call, scale, q, a, w, x): return {"t": "S", "lv": lv, "cat": cat, "call": call, "scale": scale, "q": q, "a": a, "w": w, "x": x}
def M(lv, cat, call, scale, q, opts, x):
    assert any(o[0] == "+" for o in opts) and any(o[0] == "-" for o in opts), q
    return {"t": "M", "lv": lv, "cat": cat, "call": call, "scale": scale, "q": q, "opts": opts, "x": x}

Q = []
A = Q.append
# ---------- scales (asked only for the scale the user picked) ----------
A(S("emt","medical","stroke","cpss","Which three findings make up the Cincinnati Prehospital Stroke Scale?","Facial droop, arm drift and abnormal speech",["Facial droop, grip strength and gaze deviation","Balance, vision and speech","Arm drift, leg drift and level of consciousness"],"The CPSS checks a smile for facial droop, 10 seconds of arm drift with eyes closed, and repeating a sentence."))
A(S("emt","medical","stroke","cpss","How many abnormal Cincinnati findings are needed to suspect a stroke?","One",["Two","All three","At least two plus a headache"],"Any single abnormal CPSS finding is a positive screen. With one finding the chance of stroke is about 72%; with all three it is over 85%."))
A(S("emt","medical","stroke","cpss","A positive Cincinnati Prehospital Stroke Scale tells you what?","That this could be a stroke",["That there is a large vessel occlusion","That the stroke is hemorrhagic","That the patient qualifies for thrombolysis"],"The CPSS is a screen. It does not measure severity or predict an LVO; a severity scale or the hospital exam does that."))
A(S("emt","medical","stroke","cpss","How is arm drift tested in the Cincinnati scale?","Eyes closed, both arms out with palms up for 10 seconds",["Squeeze both of your hands as hard as possible","Lift each leg off the stretcher for 5 seconds","Touch the finger to the nose with eyes open"],"Closing the eyes removes visual correction, so a weak arm drifts down or pronates."))
A(S("emt","medical","stroke","befast","What do the B and E in BE-FAST add to FAST?","Balance and eyes, to catch posterior circulation strokes",["Breathing and EKG, to catch cardiac causes","Blood glucose and eyes, to rule out mimics","Bleeding and edema, to spot hemorrhagic strokes"],"Strokes in the back of the brain (posterior circulation) often cause imbalance, vertigo or vision loss with a normal face, arm and speech exam."))
A(S("emt","medical","stroke","befast","A 62-year-old has sudden vertigo, cannot walk straight and has double vision. Face, arms and speech are normal. With BE-FAST this patient is:","Positive, because of the balance and eye findings",["Negative, because face, arm and speech are normal","Positive only if a headache is present","Negative until the symptoms last 24 hours"],"Any one sudden BE-FAST finding is positive. This is the posterior stroke picture FAST alone would miss."))
A(S("emt","medical","stroke","befast","What does the T in BE-FAST stand for?","Time: note the last known well and move quickly",["Temperature: rule out sepsis","Tongue: check for deviation","Tone: check for rigidity"],"Every stroke treatment window is measured from the last known well time."))
A(S("emt","medical","stroke","lapss","Which glucose range is required for a positive LAPSS?","60 to 400 mg/dL",["Over 60 mg/dL only","70 to 180 mg/dL","Under 400 mg/dL only"],"LAPSS requires a glucose of 60 to 400 to help screen out hypoglycemia and severe hyperglycemia as mimics."))
A(M("emt","medical","stroke","lapss","Which are LAPSS screening criteria? Select all that apply.",[("+","Age over 45"),("+","No history of seizures or epilepsy"),("+","Symptoms present less than 24 hours"),("-","Systolic blood pressure over 140"),("-","Sudden severe headache")],"LAPSS criteria: age over 45, no seizure history, symptoms under 24 hours, not wheelchair-bound or bedridden, glucose 60 to 400, and one-sided weakness of face, grip or arm."))
A(S("emt","medical","stroke","lapss","A patient has a negative LAPSS but a clear story of sudden one-sided numbness and confusion. What is the best approach?","Treat it as a possible stroke anyway",["Document a negative stroke screen and transport routinely","Recheck in 30 minutes before deciding","Obtain a refusal since the screen is negative"],"A negative LAPSS does not rule out stroke. Clinical suspicion wins."))
A(S("emt","medical","stroke","lams","What is the Los Angeles Motor Scale total that suggests a large vessel occlusion?","4 or more out of 5",["2 or more out of 5","3 or more out of 9","5 or more out of 9"],"LAMS scores facial droop 0 to 1, arm drift 0 to 2 and grip 0 to 2. A total of 4 or 5 suggests an LVO."))
A(S("emt","medical","stroke","lams","Which three items are scored in LAMS?","Facial droop, arm drift and grip strength",["Gaze, aphasia and neglect","Facial droop, speech and leg drift","Level of consciousness, gaze and arm drift"],"LAMS is a pure motor scale built from the LAPSS motor items."))
A(S("emt","medical","stroke","lams","A patient has facial droop, an arm that falls rapidly and no grip on that side. What is the LAMS?","5",["3","4","6"],"Facial droop 1 + arm falls rapidly 2 + no grip 2 = 5, which suggests an LVO."))
A(S("emt","medical","stroke","race","What RACE score suggests a large vessel occlusion?","5 or more",["2 or more","4 or more","8 or more"],"RACE runs 0 to 9; a score of 5 or more suggests an LVO."))
A(S("emt","medical","stroke","race","In RACE, when do you score agnosia instead of aphasia?","When the left side is weak",["When the right side is weak","When the patient is unconscious","When both sides are weak"],"Left-sided weakness means a right-brain stroke, which causes neglect or agnosia. Right-sided weakness means a left-brain stroke, which causes aphasia."))
A(M("emt","medical","stroke","race","Which items are scored in RACE? Select all that apply.",[("+","Facial palsy"),("+","Leg motor"),("+","Head and gaze deviation"),("-","Blood glucose"),("-","Pupil size")],"RACE scores facial palsy, arm motor, leg motor, head and gaze deviation, and aphasia or agnosia."))
A(S("emt","medical","stroke","cstat","How many points does conjugate gaze deviation earn on C-STAT?","2",["1","3","It is not part of C-STAT"],"Gaze deviation is worth 2 points, so it alone reaches the LVO cutoff of 2."))
A(S("emt","medical","stroke","cstat","What C-STAT total suggests a large vessel occlusion?","2 or more",["1 or more","3 or more","4 only"],"C-STAT runs 0 to 4; 2 or more suggests an LVO."))
A(S("emt","medical","stroke","cstat","A patient cannot hold the left arm up for 10 seconds, knows their age and the month, and follows commands. Gaze is midline. What is the C-STAT?","1, which is below the LVO cutoff",["2, which suggests an LVO","3, which suggests an LVO","0, because the arm is not scored"],"Only arm weakness scores (1 point). The LOC point needs a wrong answer AND a failed command."))
A(S("emt","medical","stroke","fasted","What FAST-ED score suggests a large vessel occlusion?","4 or more",["2 or more","6 or more","9 only"],"FAST-ED runs 0 to 9; 4 or more suggests an LVO."))
A(S("emt","medical","stroke","fasted","What do the E and D in FAST-ED stand for?","Eye deviation and denial or neglect",["EKG and dysarthria","Edema and deficit","Extremity and drift"],"Eye deviation and denial or neglect are cortical signs that point to a large clot."))
A(S("emt","medical","stroke","fasted","Facial palsy (1), arm falls (2), mild aphasia (1), no eye deviation, no neglect. What is the FAST-ED and what does it suggest?","4, which suggests an LVO",["3, which does not suggest an LVO","4, which rules out a stroke","6, which suggests hemorrhage"],"1 + 2 + 1 + 0 + 0 = 4, the LVO cutoff."))
A(S("emt","medical","stroke","van","What must be present before the rest of the VAN assessment counts?","Arm weakness",["Facial droop","Altered mental status","A severe headache"],"VAN starts with arm weakness. No weakness means VAN negative."))
A(S("emt","medical","stroke","van","A patient has right arm drift and cannot name objects. Vision and attention are normal. The VAN is:","Positive, from weakness plus aphasia",["Negative, because vision is normal","Positive only with gaze deviation","Negative, because only one cortical sign is present"],"VAN positive = arm weakness plus any one of vision, aphasia or neglect."))
A(S("emt","medical","stroke","van","A patient has left arm weakness only. Speech, vision and attention are normal. The VAN is:","Negative",["Positive","Indeterminate until a glucose is checked","Positive if the weakness is severe"],"Weakness alone, without a vision, aphasia or neglect finding, is VAN negative."))
A(S("emt","medical","stroke","mend","What are the three parts of the MEND exam?","Mental status, cranial nerves and limbs",["Airway, breathing and circulation","Motor, eyes, neglect and drift","Mood, energy, nutrition and dexterity"],"MEND checks mental status, cranial nerves (face, fields, gaze) and limbs (drift, sensation, coordination)."))
A(S("emt","medical","stroke","mend","Which scale is built into the MEND exam?","The Cincinnati Prehospital Stroke Scale",["The Glasgow Coma Scale","The RACE scale","The Los Angeles Motor Scale"],"MEND includes facial droop, arm drift and speech, so it also answers the CPSS."))
A(S("emt","medical","stroke","mend","How is the MEND exam scored?","Any abnormal finding is a positive exam",["It is scored 0 to 42","A total of 4 or more is positive","Only gaze deviation counts"],"MEND is a checklist rather than a point score."))
A(S("paramedic","medical","stroke","nihss","What is the range of the NIH Stroke Scale?","0 to 42",["0 to 9","3 to 15","0 to 100"],"NIHSS runs 0 (no deficit) to 42."))
A(S("paramedic","medical","stroke","nihss","What NIHSS is the usual minimum for thrombectomy of an anterior LVO?","6",["1","10","15"],"The 2026 guideline uses NIHSS 6 or more for anterior LVO thrombectomy (10 or more for basilar occlusion)."))
A(S("paramedic","medical","stroke","nihss","A patient has NIHSS 3 from isolated severe aphasia that keeps them from working or communicating. Under the 2026 guideline, are they a thrombolysis candidate within 4.5 hours?","Yes, because the deficit is disabling",["No, because the NIHSS is under 6","No, because aphasia is excluded","Only if a perfusion scan is done first"],"Thrombolysis is for disabling deficits regardless of the NIHSS number."))
# ---------- stroke general ----------
A(S("emt","medical","stroke",None,"What is the key difference between a TIA and a stroke?","A TIA leaves no infarct on imaging; a stroke does",["A TIA is always under 5 minutes","A TIA only affects speech","A TIA cannot be treated"],"A TIA is a brief blockage without dead tissue. You cannot tell them apart in the field, so active symptoms are treated as a stroke."))
A(S("emt","medical","stroke",None,"A 70-year-old had 20 minutes of right arm weakness that has fully resolved. Now he wants to stay home. What is the best response?","Explain that stroke risk is highest in the next 48 hours and encourage transport",["Agree, since the symptoms resolved","Have him follow up with his doctor next week","Transport only if the blood pressure is high"],"A TIA is a warning sign; urgent evaluation lowers the risk of a disabling stroke."))
A(S("emt","medical","stroke",None,"A woman went to bed at 22:00 normal and woke at 06:00 with left-sided weakness. What is her last known well?","22:00",["06:00","The time EMS arrived","Unknown, so no time is recorded"],"Wake-up stroke: LKW is when she was last seen normal, not when symptoms were found."))
A(S("emt","medical","stroke",None,"Symptoms started at 13:00, fully resolved at 13:30, then returned at 15:00. What is the last known well?","13:30",["13:00","15:00","Unknown"],"A complete return to baseline resets the clock to the time they were last fully normal."))
A(S("emt","medical","stroke",None,"Symptoms started at 09:00 and partly improved at 09:40 but never fully cleared. What is the last known well?","09:00",["09:40","The time of arrival","Unknown"],"Only a full return to baseline resets the clock. Partial improvement does not."))
A(S("emt","medical","stroke",None,"What is the single most important stroke mimic to rule out in the field?","Hypoglycemia",["Bell's palsy","Migraine","Conversion disorder"],"Low glucose can cause any focal deficit and is quickly reversible. Check a glucose on every suspected stroke."))
A(M("emt","medical","stroke",None,"Which are classic stroke mimics? Select all that apply.",[("+","Postictal (Todd's) paralysis"),("+","Complex migraine"),("+","Hypoglycemia"),("-","Atrial fibrillation"),("-","Carotid stenosis")],"Atrial fibrillation and carotid stenosis are stroke causes, not mimics."))
A(S("emt","medical","stroke",None,"Which finding points to Bell's palsy rather than a stroke?","The forehead on the affected side cannot wrinkle",["Arm drift on the same side","Slurred speech","Forced gaze to one side"],"Bell's palsy weakens the whole side of the face, forehead included. A stroke usually spares the forehead."))
A(S("paramedic","medical","stroke",None,"Why can dropping the blood pressure worsen a swelling ischemic brain?","CPP = MAP - ICP, so a lower MAP with a high ICP cuts perfusion to the penumbra",["Lower pressure increases bleeding into the clot","Low pressure raises intracranial pressure directly","It prevents thrombolytics from working"],"Autoregulation is lost around the stroke, so flow follows pressure. Less flow turns penumbra into core and worsens swelling."))
A(S("paramedic","medical","stroke",None,"What is the penumbra?","Stunned but still living brain around the dead core",["The dead core of the infarct","Blood that has leaked into the brain","The swelling seen 3 days after a stroke"],"Saving the penumbra is the whole point of reperfusion and of protecting blood pressure."))
A(S("paramedic","medical","stroke",None,"In many EMS systems, when is the blood pressure of a suspected ischemic stroke treated in the field?","Only when it is over 220/120 (or per medical control)",["Whenever it is over 140/90","Whenever it is over 160/100","Never, under any circumstances"],"Permissive hypertension protects the penumbra. The hospital lowers it to under 185/110 only if thrombolysis is planned."))
A(S("paramedic","medical","stroke",None,"What blood pressure must be reached before IV thrombolysis for stroke?","Under 185/110",["Under 140/90","Under 160/100","Under 220/120"],"After thrombolysis it is kept under 180/105 for 24 hours."))
A(S("paramedic","medical","stroke",None,"After a successful thrombectomy, what does the 2026 guideline say about lowering systolic BP below 140?","It is harmful and not recommended",["It is required for 72 hours","It is optional","It is recommended only for large-core strokes"],"Intensive lowering below 140 after recanalization worsened outcomes in trials."))
A(S("emt","medical","stroke",None,"Under the 2026 AHA/ASA guideline, what is the standard window for IV thrombolysis for stroke?","Within 4.5 hours of last known well",["Within 3 hours of symptom discovery","Within 6 hours of last known well","Within 24 hours of last known well"],"0 to 4.5 hours from LKW for eligible patients with disabling deficits."))
A(S("paramedic","medical","stroke",None,"A wake-up stroke patient was last seen normal 8 hours ago. Under the 2026 guideline, can thrombolysis still be considered?","Yes, if advanced imaging shows salvageable brain (for example DWI-FLAIR mismatch)",["No, the window is 4.5 hours with no exceptions","Yes, with no imaging needed","Only if the NIHSS is over 20"],"Extended-window thrombolysis (about 4.5 to 9 hours or unknown onset) may be considered with imaging selection."))
A(S("paramedic","pharm","stroke",None,"Which statement about tenecteplase versus alteplase for stroke is correct under the 2026 guideline?","Either may be used within 4.5 hours; tenecteplase is a single IV push",["Only alteplase is recommended","Tenecteplase requires a 60-minute infusion","Tenecteplase is only for patients over 80"],"The 2026 guideline endorses both. Tenecteplase's single bolus makes transfers simpler than alteplase's 60-minute infusion."))
A(S("paramedic","pharm","stroke",None,"Why can tenecteplase be given as one push while alteplase needs an infusion?","Tenecteplase has a longer half-life and more fibrin specificity",["Tenecteplase is a smaller dose of the same drug","Alteplase is only absorbed slowly","Tenecteplase does not need to reach the clot"],"Tenecteplase was engineered from alteplase to last longer and bind fibrin more selectively."))
A(S("paramedic","pharm","stroke",None,"What does the 2026 guideline say about the higher tenecteplase dose used in some trials?","It is not recommended because it did not help and may cause harm",["It is preferred for basilar occlusion","It is preferred for patients over 100 kg","It is recommended after 4.5 hours"],"Only the standard stroke dose is recommended."))
A(S("paramedic","pharm","stroke",None,"A patient has a mild, non-disabling stroke 2 hours after onset. What does the 2026 guideline prefer?","Dual antiplatelet therapy rather than thrombolysis",["Thrombolysis regardless of deficit","Thrombectomy","No treatment"],"Thrombolysis has not been shown to help non-disabling deficits; DAPT is preferred."))
A(M("paramedic","pharm","stroke",None,"Which would make a stroke patient ineligible for IV thrombolysis? Select all that apply.",[("+","Blood on the CT scan"),("+","Blood pressure that cannot be brought under 185/110"),("+","Glucose of 40 mg/dL"),("-","Age over 80"),("-","Atrial fibrillation not on an anticoagulant")],"Age alone and untreated atrial fibrillation are not exclusions. Low glucose must be corrected and reassessed because it may be the cause."))
A(S("emt","medical","stroke",None,"Which hospitals can perform endovascular thrombectomy?","Comprehensive and Thrombectomy-capable Stroke Centers",["Any Primary Stroke Center","Acute Stroke Ready Hospitals","Any emergency department with a CT"],"Primary Stroke Centers and Acute Stroke Ready Hospitals can give thrombolysis but not thrombectomy."))
A(S("emt","medical","stroke",None,"Which findings most strongly suggest a large vessel occlusion?","Gaze deviation, aphasia or neglect with dense one-sided weakness",["Isolated numbness of one hand","Dizziness alone","Mild facial droop only"],"Cortical signs plus dense weakness are the classic LVO picture, which is what the severity scales measure."))
A(S("emt","ops","stroke",None,"Your severity scale is positive for LVO, LKW was 2 hours ago, and a thrombectomy center is 20 minutes farther than the nearest primary stroke center. Under the AHA Mission: Lifeline routing algorithm, where should most systems go?","The thrombectomy-capable center",["The nearest primary stroke center","Whichever hospital the family prefers","Any ED with a CT"],"Suspected LVO goes to a CSC or TSC when the extra time is about 30 minutes or less and thrombolysis eligibility is not lost. Local protocols set exact minutes."))
A(S("emt","ops","stroke",None,"When does a suspected LVO patient go to the nearest stroke center instead of bypassing to a thrombectomy center?","When the bypass would push a thrombolysis-eligible patient past their window",["Whenever the patient is over 80","Whenever the blood pressure is high","When the patient is on aspirin"],"Getting thrombolysis started (drip and ship) can come first when the bypass costs the window."))
A(S("paramedic","medical","stroke",None,"What is the standard time window for thrombectomy of an anterior LVO without advanced imaging selection?","0 to 6 hours from last known well",["0 to 3 hours","0 to 4.5 hours","0 to 48 hours"],"Up to 6 hours is the early window; 6 to 24 hours needs imaging selection."))
A(S("paramedic","medical","stroke",None,"Up to how long after last known well can selected anterior LVO patients get a thrombectomy?","24 hours",["6 hours","12 hours","72 hours"],"From 6 to 24 hours, patients are selected by imaging; the 2026 guideline now includes some large-core strokes."))
A(S("paramedic","medical","stroke",None,"For basilar artery occlusion, the 2026 guideline supports thrombectomy within 24 hours for patients with which NIHSS?","10 or more",["1 or more","6 or more","20 or more"],"Benefit for NIHSS 6 to 9 in basilar occlusion is not well established."))
A(S("emt","ops","stroke",None,"What is the field scene-time goal for a suspected stroke?","15 minutes or less",["30 minutes or less","5 minutes or less","No target; take as long as needed"],"Short scene times and pre-notification shorten door-to-needle and door-to-puncture times."))
A(O_ := {"t": "O", "lv": "emt", "cat": "medical", "call": "stroke", "scale": None, "q": "Put these stroke actions in order, first to last.", "opts": ["Check the airway, breathing and circulation", "Check a blood glucose", "Run the stroke screen and severity scale", "Pin down the last known well time and a witness phone number", "Pre-notify the stroke destination"], "x": "Life threats, then the most common treatable mimic, then the exam, the clock and the call ahead."})
A(S("emt","medical","stroke",None,"What SpO2 is the usual threshold for giving oxygen to a stroke patient?","Under 94%",["Under 98%","Under 90% only in COPD","Oxygen for everyone regardless of SpO2"],"Routine oxygen for a normal saturation does not help stroke outcomes."))
A(S("emt","medical","stroke",None,"Why should a stroke patient have nothing by mouth?","Swallowing may be impaired and aspiration is common",["Food raises blood pressure","Food interferes with CT scans","Eating triggers seizures"],"Dysphagia is common after stroke; the hospital screens the swallow first."))
# ---------- STEMI ----------
A(S("emt","cardio","stemi",None,"How soon after first medical contact should a 12-lead be obtained in suspected ACS?","Within 10 minutes",["Within 30 minutes","On arrival at the hospital","Only if the pain is severe"],"Early 12-leads let EMS activate the cath lab from the field."))
A(S("paramedic","cardio","stemi",None,"What is the ST elevation threshold for V2 and V3 in a woman?","1.5 mm",["1 mm","2 mm","2.5 mm"],"In V2-V3: 1.5 mm in women, 2 mm in men 40 and over, 2.5 mm in men under 40. Other leads: 1 mm."))
A(S("paramedic","cardio","stemi",None,"ST elevation in II, III and aVF points to which territory?","Inferior, usually the right coronary artery",["Anterior, the LAD","Lateral, the circumflex","Septal only"],"Inferior STEMI: check right-sided V4R for right ventricular involvement."))
A(S("paramedic","cardio","stemi",None,"Inferior STEMI with 1 mm ST elevation in V4R and a BP of 92/60. Which drug is most likely to drop the pressure dangerously?","Nitroglycerin",["Aspirin","Oxygen","Normal saline"],"Right ventricular infarcts are preload-dependent; nitrates reduce preload and can crash the pressure."))
A(S("paramedic","cardio","stemi",None,"ST depression in V1 to V3 with tall R waves suggests what?","Posterior MI",["Normal variant","Pericarditis","Digoxin effect only"],"Confirm with posterior leads V7 to V9: 0.5 mm of elevation."))
A(S("paramedic","cardio","stemi",None,"What is the elevation threshold in posterior leads V7 to V9?","0.5 mm",["1 mm","2 mm","3 mm"],"Posterior leads are far from the heart, so the cutoff is lower."))
A(S("paramedic","cardio","stemi",None,"Upsloping ST depression with tall symmetric T waves across V1 to V6 in chest pain suggests what?","De Winter T waves, a proximal LAD occlusion",["Hyperkalemia only","Early repolarization","Wellens syndrome"],"De Winter is a STEMI equivalent that deserves cath lab activation per protocol."))
A(S("paramedic","cardio","stemi",None,"A pain-free patient has deep biphasic T waves in V2 and V3 after chest pain yesterday. What is this, and why does it matter?","Wellens pattern: critical LAD narrowing at risk of closing",["Normal variant","A completed old MI","Pericarditis"],"Wellens is not a STEMI, but these patients need urgent cardiology and should not get stress testing."))
A(S("paramedic","cardio","stemi",None,"Which criteria help find an MI in a patient with left bundle branch block or a paced rhythm?","Sgarbossa (or modified Smith-Sgarbossa)",["Wellens criteria","Brugada criteria","Duke criteria"],"Concordant ST elevation of 1 mm or more, concordant ST depression of 1 mm or more in V1 to V3, or excessively discordant elevation."))
A(S("paramedic","cardio","stemi",None,"ST elevation in aVR with widespread ST depression suggests what?","Left main or multivessel ischemia",["A normal ECG","Isolated right ventricular infarct","Early repolarization"],"High-risk pattern; follow your protocol on activation."))
A(S("emt","cardio","stemi",None,"EMS takes a STEMI patient directly to a PCI-capable center. What is the first-medical-contact-to-device goal?","90 minutes or less",["30 minutes or less","120 minutes or less","180 minutes or less"],"Direct transport: FMC to device within 90 minutes."))
A(S("paramedic","cardio","stemi",None,"When is fibrinolysis chosen over transfer for PCI in STEMI?","When FMC to device would exceed 120 minutes, within 12 hours of onset",["Whenever the patient is over 75","Only after a failed PCI","Whenever the pain is under 1 hour"],"If PCI cannot happen within 120 minutes, fibrinolysis (door to needle within 30 minutes) is the alternative."))
A(S("paramedic","cardio","stemi",None,"What is the door-in-door-out goal at a non-PCI hospital transferring a STEMI?","30 minutes or less",["60 minutes or less","90 minutes or less","10 minutes or less"],"DIDO of 30 minutes keeps FMC to device near 120 minutes."))
A(S("emt","cardio","stemi",None,"When is oxygen indicated in suspected ACS?","SpO2 under 90% or respiratory distress",["For every chest pain patient","Only for STEMI","Only if the patient is over 65"],"Extra oxygen does not help a normal saturation."))
A(M("emt","cardio","stemi",None,"Which findings mean nitroglycerin is held in chest pain? Select all that apply.",[("+","Systolic BP under 90"),("+","Sildenafil taken 6 hours ago"),("+","Right ventricular infarct"),("-","Heart rate of 88"),("-","History of high cholesterol")],"Also held for tadalafil within 48 hours or a pressure 30 below baseline."))
A(M("paramedic","cardio","stemi",None,"Which are absolute contraindications to fibrinolysis for STEMI? Select all that apply.",[("+","Any prior intracranial hemorrhage"),("+","Suspected aortic dissection"),("+","Ischemic stroke 6 weeks ago"),("-","Age over 75"),("-","Blood pressure of 150/90")],"Age and a controlled BP are not absolute contraindications."))
A(S("emt","cardio","stemi",None,"Why are defibrillation pads placed early on a STEMI patient?","Ventricular fibrillation is most common in the first hours",["To get a better 12-lead","To pace every patient","To monitor blood pressure"],"Early VF is the most common cause of sudden death in STEMI."))
# ---------- sepsis ----------
A(S("emt","medical","sepsis",None,"Which best defines sepsis?","Life-threatening organ dysfunction from the body's response to infection",["Any fever over 38 C","Bacteria in the blood","Infection with a fast heart rate"],"Sepsis-3 definition."))
A(S("emt","medical","sepsis",None,"Which qSOFA finding is NOT one of the three criteria?","Heart rate over 100",["Respiratory rate 22 or more","Altered mentation","Systolic BP 100 or less"],"qSOFA is respiratory rate, mentation and systolic BP. The 2021 Surviving Sepsis Campaign advises against using it alone as a screen."))
A(S("paramedic","medical","sepsis",None,"A low end-tidal CO2 in a suspected sepsis patient often correlates with what?","A high lactate",["A low glucose","A high potassium","Normal perfusion"],"EtCO2 of about 25 mmHg or less tracks with elevated lactate and poor perfusion."))
A(S("paramedic","medical","sepsis",None,"What defines septic shock?","Vasopressors needed for MAP 65 or more and lactate over 2 despite fluids",["Any hypotension with fever","Heart rate over 120","Lactate over 1"],"Septic shock carries a much higher mortality than sepsis alone."))
A(S("emt","medical","sepsis",None,"What is the antibiotic time goal for septic shock?","Within 1 hour of recognition",["Within 6 hours","Within 24 hours","After cultures result"],"Each hour of delay raises mortality; a field sepsis alert speeds this up."))
A(S("paramedic","medical","sepsis",None,"During fluid resuscitation in sepsis, what should be reassessed between boluses?","Lung sounds, breathing and perfusion",["Pupil size","Grip strength","Capillary glucose only"],"Fluids help until they cause pulmonary edema; reassess each time."))
# ---------- trauma ----------
A(M("emt","trauma","trauma",None,"Which are RED criteria in the 2021 field triage guideline? Select all that apply.",[("+","Suspected pelvic fracture"),("+","Amputation above the wrist"),("+","Motor GCS under 6"),("-","Fall from 8 feet"),("-","Single closed forearm fracture")],"Red criteria go to the highest level trauma center."))
A(S("emt","trauma","trauma",None,"In the 2021 field triage guideline, which vital sign is a red criterion for an adult aged 10 to 64?","Heart rate greater than systolic BP",["Heart rate over 100","Systolic BP under 110","SpO2 under 95%"],"For 10 to 64: SBP under 90 or HR greater than SBP. For 65 and over: SBP under 110 or HR greater than SBP."))
A(S("emt","trauma","trauma",None,"What systolic BP is a red criterion for a patient 65 or older?","Under 110",["Under 90","Under 100","Under 80"],"Older adults decompensate at higher pressures."))
A(S("emt","trauma","trauma",None,"A fall from what height is a yellow (mechanism) criterion for all ages?","Over 10 feet",["Over 20 feet","Over 3 feet","Any fall"],"The 2021 guideline uses 10 feet for all ages."))
A(S("emt","trauma","trauma",None,"What are the parts of the trauma lethal triad?","Hypothermia, acidosis and coagulopathy",["Hypoxia, hypotension and hypoglycemia","Bradycardia, hypertension and irregular breathing","Fever, tachycardia and hypotension"],"Each worsens the others; keep trauma patients warm from the start."))
A(S("paramedic","trauma","trauma",None,"Which patient should NOT get permissive hypotension?","A patient with a traumatic brain injury",["A stab wound to the abdomen with no head injury","A gunshot to the torso","A patient with a pelvic fracture and no head injury"],"The injured brain needs a normal blood pressure for perfusion."))
A(S("paramedic","trauma","trauma",None,"Tranexamic acid for trauma bleeding is not started after how long from injury?","3 hours",["1 hour","6 hours","24 hours"],"Benefit is greatest within 1 hour; after 3 hours it may cause harm."))
# ---------- ROSC ----------
A(S("emt","cardio","rosc",None,"After ROSC, what SpO2 range is targeted?","92 to 98%",["100%","88 to 92%","Over 85%"],"Hyperoxia after arrest is harmful."))
A(S("paramedic","cardio","rosc",None,"After ROSC, what end-tidal CO2 range is targeted?","35 to 45 mmHg",["20 to 25 mmHg","50 to 60 mmHg","Under 30 mmHg"],"Hyperventilation lowers CO2 and constricts cerebral vessels."))
A(S("paramedic","cardio","rosc",None,"After ROSC, what blood pressure goals are typical?","Systolic 90 or more and MAP 65 or more",["Systolic 140 or more","MAP 50 or more","Any pressure with a pulse"],"Treat hypotension with fluids and vasopressors per protocol."))
A(S("paramedic","cardio","rosc",None,"During post-ROSC care, the end-tidal CO2 suddenly falls from 38 to 12. What is the most likely cause?","Re-arrest",["Improved perfusion","Hyperventilation only","A normal finding"],"Check a pulse and resume CPR if absent."))
A(S("emt","cardio","rosc",None,"Why is a 12-lead obtained soon after ROSC?","To find a STEMI that needs the cath lab",["To check the defibrillator","To measure blood pressure","To confirm the patient's identity"],"Post-arrest STEMI goes to a PCI center."))
